  object.set("data", emscripten::val::undefined());

  std::unique_ptr<LIEF::PE::Binary> binary =
      LIEF::PE::Parser::parse(vec_from_val(executable));

  if (!binary) {
    object.set("result", emscripten::val(InjectResult::kError));
    return object;
  }

