4: 
5: import { spawnSync, execSync } from "child_process";
6: import * as crypto from "crypto";
7: import * as path from "path";
8: import * as os from "os";
9: 
10: import { default as chai, expect } from "chai";
11: import chaiAsPromised from "chai-as-promised";
