13: 
14: import fs from "fs-extra";
15: import rimraf from "rimraf";
16: import { temporaryDirectory } from "tempy";
17: 
18: // TODO - More test coverage
19: describe("postject CLI", () => {
20:   let filename;
21:   let tempDir;
22:   let resourceContents;
23:   let resourceFilename;
24:   const IS_WINDOWS = os.platform() === "win32";
25: 
26:   beforeEach(async () => {
27:     let originalFilename;
28: 
29:     tempDir = temporaryDirectory();
30:     await fs.ensureDir(tempDir);
31: 
32:     if (IS_WINDOWS) {
33:       originalFilename = "./build/test/Debug/cpp_test.exe";
34:       filename = path.join(tempDir, "cpp_test.exe");
35:     } else {
36:       originalFilename = "./build/test/cpp_test";
37:       filename = path.join(tempDir, "cpp_test");
38:     }
39: 
40:     await fs.copy(originalFilename, filename);
41: 
42:     resourceContents = crypto.randomBytes(64).toString("hex");
43:     resourceFilename = path.join(tempDir, "resource.bin");
44:     await fs.writeFile(resourceFilename, resourceContents);
45:   });
46: 
47:   afterEach(() => {
48:     rimraf.sync(tempDir);
49:   });
50: 
51:   it("should have help output", async () => {
52:     const { status, stdout } = spawnSync("node", ["./dist/cli.js", "-h"], {
53:       encoding: "utf-8",
54:     });
55:     expect(status).to.equal(0);
56:     expect(stdout).to.have.string("Usage");
57:   });
58: 
59:   it("has required arguments", async () => {
60:     const { status, stderr } = spawnSync("node", ["./dist/cli.js"], {
61:       encoding: "utf-8",
62:     });
63:     expect(status).to.equal(1);
64:     expect(stderr).to.have.string("required");
65:   });
66: 
67:   it("should inject a resource successfully", async () => {
68:     // Before injection
69:     {
70:       const { status, stdout } = spawnSync(filename, { encoding: "utf-8" });
71:       expect(status).to.equal(0);
72:       expect(stdout).to.have.string("Hello world");
73:     }
74: 
75:     {
76:       const { status, stdout, stderr } = spawnSync(
77:         "node",
78:         [
79:           "./dist/cli.js",
80:           filename,
81:           "foobar",
82:           resourceFilename,
83:           "--sentinel-fuse",
84:           "NODE_JS_FUSE_fce680ab2cc467b6e072b8b5df1996b2",
85:         ],
86:         { encoding: "utf-8" }
87:       );
88:       // TODO(dsanders11) - Enable this once we squelch LIEF warnings
89:       // expect(stderr).to.be.empty;
90:       expect(stdout).to.have.string("Injection done!");
91:       expect(status).to.equal(0);
92:     }
93: 
94:     // Verifying code signing using a self-signed certificate.
95:     {
96:       if (process.platform === "darwin") {
97:         let codesignFound = false;
98:         try {
99:           execSync("command -v codesign");
